import { afterAll, beforeAll, expect, test } from 'vitest'
import { chromium, type Browser } from 'playwright'
import { getPlatformProxy } from 'wrangler'
import server from '../../server'
import { applyMigrations } from '../db/test-migrations'
import { TEST_ORIGIN, testEnv } from '../publication/test-support'
import { japaneseOutside } from './test-japanese'

// The pages are generated by `pnpm build`; CI builds before testing.
const platform = await getPlatformProxy<Env>({ persist: false })
const env = testEnv(platform.env)

let browser: Browser
beforeAll(async () => {
  await applyMigrations(platform.env.DB)
  browser = await chromium.launch()
})
afterAll(async () => {
  await browser?.close()
  await platform.dispose()
})

/** Opens the top page through the Worker, so the page CSP applies. */
async function openTop(path: string, width = 390) {
  const page = await browser.newPage({ viewport: { width, height: 844 } })
  const errors: string[] = []
  page.on('console', (message) => {
    if (message.type() === 'error') errors.push(message.text())
  })
  page.on('pageerror', (error) => errors.push(error.message))
  await page.route('**/*', async (route) => {
    const url = new URL(route.request().url())
    if (url.origin !== TEST_ORIGIN) return route.abort()
    // Miniflare's local proxy refuses a foreign Origin; see home.browser.test.
    const { origin: _origin, ...headers } = await route.request().allHeaders()
    const response = await server.fetch(new Request(url, { headers }), env)
    await route.fulfill({
      status: response.status,
      headers: Object.fromEntries(response.headers),
      body: Buffer.from(await response.arrayBuffer()),
    })
  })
  await page.goto(`${TEST_ORIGIN}${path}`)
  await page.waitForLoadState('networkidle')
  /** The figure beside a section's heading. */
  const figure = (id: string) =>
    page.locator(`#${id}`).locator('xpath=../..').locator('.feature-figure')
  return { page, figure, errors }
}

const LANGUAGES = [
  {
    path: '/?lang=ja',
    popup: '別タブを開く',
    blocked: 'sandbox が遮断（allow-popups なし）',
    form: 'フォームを送る',
    formBlocked: 'allow-forms なし',
    context: '文脈が足りる 5/5',
    concrete: '具体的',
    noteLabel: '発表者のノート · p.14',
    slides: 'スライドでめくる',
    notes: 'ノートで読む',
    secondSlide: '指数バックオフ',
  },
  {
    path: '/?lang=en',
    popup: 'Open another tab',
    blocked: 'Blocked by the sandbox (no allow-popups)',
    form: 'Submit a form',
    formBlocked: 'no allow-forms',
    context: 'Enough context 5/5',
    concrete: 'Concrete',
    noteLabel: 'Speaker notes · p.14',
    slides: 'Flip through slides',
    notes: 'Read with notes',
    secondSlide: 'Exponential backoff',
  },
] as const

test.each(LANGUAGES)(
  'Given the top page $path, When the reader presses what the stranger’s slide tries, Then the log shows the sandbox refusing it',
  async (words) => {
    const { page, figure, errors } = await openTop(words.path)
    const sandbox = figure('touch-safe')
    const log = sandbox.locator('.mock-log')
    const code = sandbox.locator('.mock-code')
    expect(await log.textContent()).toContain('▶')

    await sandbox.getByRole('button', { name: words.popup }).click()
    await expect.poll(() => log.textContent()).toContain(words.blocked)
    expect(await code.textContent()).toContain('window.open(')
    expect(
      await sandbox
        .getByRole('button', { name: words.popup })
        .getAttribute('aria-pressed'),
    ).toBe('true')

    await sandbox.getByRole('button', { name: words.form }).click()
    await expect.poll(() => log.textContent()).toContain(words.formBlocked)
    expect(await code.textContent()).toContain('form.submit()')
    expect(
      await sandbox.locator('button[aria-pressed="true"]').allTextContents(),
    ).toEqual([words.form])
    expect(errors).toEqual([])
    await page.close()
  },
)

test.each(LANGUAGES)(
  'Given the top page $path, When the reader chooses a review axis, Then the finding shows that axis alone',
  async (words) => {
    const { page, figure, errors } = await openTop(words.path)
    const review = figure('touch-review')
    const finding = review.locator('.mock-finding')
    const pressed = review.locator('.mock-axes [aria-pressed="true"]')
    const first = await finding.locator('b').textContent()

    await review.locator('.mock-axes button').nth(1).click()
    await expect
      .poll(() => finding.locator('b').textContent())
      .toBe(words.context)
    expect(await pressed.count()).toBe(1)
    expect(await pressed.locator('span').first().textContent()).toBe(
      words.context.replace(/ 5\/5$/, ''),
    )
    expect(await finding.locator('small').textContent()).toBe('p.1–3')

    await review.getByRole('button', { name: words.concrete }).click()
    await expect
      .poll(() => finding.locator('b').textContent())
      .toBe(`${words.concrete} 4/5`)
    await review.locator('.mock-axes button').first().click()
    await expect.poll(() => finding.locator('b').textContent()).toBe(first)
    expect(errors).toEqual([])
    await page.close()
  },
)

test.each(LANGUAGES)(
  'Given the top page $path, When the reader switches the notes card, Then it shows the speaker’s notes or flips through the slides',
  async (words) => {
    const { page, figure, errors } = await openTop(words.path)
    const card = figure('learn-notes')
    const notes = card.locator('.mock-notes')
    const flip = card.locator('.mock-flip')
    // Notes first, each marked as what the speaker said over its slide.
    expect(await notes.isVisible()).toBe(true)
    expect(await flip.isVisible()).toBe(false)
    expect(
      await notes.locator('.mock-speaker small').first().textContent(),
    ).toBe(words.noteLabel)

    await card.getByRole('button', { name: words.slides }).click()
    await expect.poll(() => flip.isVisible()).toBe(true)
    expect(await notes.isVisible()).toBe(false)
    const previous = flip.locator('.mock-pager button').first()
    const next = flip.locator('.mock-pager button').last()
    expect(await previous.isDisabled()).toBe(true)
    await next.click()
    await expect
      .poll(() => flip.locator('.mock-cover div').textContent())
      .toBe(words.secondSlide)
    expect(await flip.locator('.mock-no').textContent()).toBe('15')
    await next.click()
    expect(await next.isDisabled()).toBe(true)
    await previous.click()
    await expect.poll(() => flip.locator('.mock-no').textContent()).toBe('15')

    await card.getByRole('button', { name: words.notes }).click()
    await expect.poll(() => notes.isVisible()).toBe(true)
    expect(await flip.isVisible()).toBe(false)

    if (words.path.endsWith('en'))
      expect(japaneseOutside(await page.content())).toEqual([])
    expect(errors).toEqual([])
    await page.close()
  },
)

test.each([320, 390, 800, 1200])(
  'Given a %ipx screen, When every live figure is in its widest state, Then nothing leaves the page or its frame',
  async (width) => {
    const { page, figure } = await openTop('/?lang=ja', width)
    await figure('touch-safe')
      .getByRole('button', { name: 'フォームを送る' })
      .click()
    await figure('learn-notes')
      .getByRole('button', { name: 'スライドでめくる' })
      .click()
    const overflow = await page.evaluate(
      () => document.documentElement.scrollWidth - window.innerWidth,
    )
    expect(overflow).toBeLessThanOrEqual(0)
    for (const id of ['touch-safe', 'touch-review', 'learn-notes']) {
      const outside = await figure(id).evaluate((frame) => {
        const box = frame.getBoundingClientRect()
        return [...frame.querySelectorAll('*')].filter((element) => {
          const part = element.getBoundingClientRect()
          return part.width > 0 && part.right > box.right + 0.5
        }).length
      })
      expect(outside, id).toBe(0)
    }
    await page.close()
  },
)
